CREATE FUNCTION [dbo].[C_TARAZ_ANBAR_SUB] (@FORMS___F_MENU_ANBAR_TARAZ___DT2 AS INT ) RETURNS TABLE AS RETURN ( SELECT     dbo.INVO_LST.ANBAR, dbo.INVO_LST.CODE, SUM(dbo.INVO_LST.MEGHk - dbo.INVO_LST.MEGH_MAR) AS MEG,  SUM(dbo.INVO_LST.AVRAGE * dbo.INVO_LST.MEGHk - ISNULL(dbo.INVO_LST.AVRAGE, 0) * dbo.INVO_LST.MEGH_MAR) AS avgofmabl,                 dbo.INVO_LST.TAG FROM         dbo.INVO_LST INNER JOIN  dbo.HEAD_LST ON dbo.INVO_LST.NUMBER = dbo.HEAD_LST.NUMBER AND dbo.INVO_LST.TAG = dbo.HEAD_LST.TAG WHERE     (dbo.INVO_LST.TAG = 2 OR dbo.INVO_LST.TAG = 5 OR  dbo.INVO_LST.TAG = 8 OR  dbo.INVO_LST.TAG = 10 OR  dbo.INVO_LST.TAG = 11 OR  dbo.INVO_LST.TAG = 26) AND (dbo.HEAD_LST.DATE_N <= @FORMS___F_MENU_ANBAR_TARAZ___DT2) GROUP BY dbo.INVO_LST.ANBAR, dbo.INVO_LST.CODE, dbo.INVO_LST.TAG  UNION  SELECT     dbo.ANBGRD_HEAD.GRD_ANBAR AS anbar, dbo.ANBGRD_LST.CODE, dbo.ANBGRD_LST.MOG - dbo.ANBGRD_LST.NUM3 AS MEG, ABS(dbo.ANBGRD_LST.MOG - dbo.ANBGRD_LST.NUM3) * dbo.ANBGRD_LST.MABL AS MABLK,18  AS TAG1  FROM         dbo.ANBGRD_LST INNER JOIN   dbo.ANBGRD_HEAD ON dbo.ANBGRD_LST.GRD_NUM = dbo.ANBGRD_HEAD.GRD_NUM  WHERE     (dbo.ANBGRD_LST.MOG - dbo.ANBGRD_LST.NUM3 > 0) AND (dbo.ANBGRD_HEAD.GRD_DATE <= @FORMS___F_MENU_ANBAR_TARAZ___DT2) AND   (NOT (dbo.ANBGRD_HEAD.N_S IS NULL)) UNION  SELECT     dbo.INVO_LST.ANBAR, dbo.INVO_LST.CODE, SUM(dbo.INVO_LST.MEGHk - dbo.INVO_LST.MEGH_MAR) AS MEG, SUM(dbo.INVO_LST.AVRAGE*(dbo.INVO_LST.MEGHk - dbo.INVO_LST.MEGH_MAR))  AS SumOfMABL_K, dbo.INVO_LST.TAG FROM         dbo.INVO_LST INNER JOIN  dbo.HEAD_LST ON dbo.INVO_LST.NUMBER = dbo.HEAD_LST.NUMBER AND dbo.INVO_LST.TAG = dbo.HEAD_LST.TAG WHERE     (dbo.INVO_LST.TAG = 1 OR  dbo.INVO_LST.TAG = 7 OR  dbo.INVO_LST.TAG = 9 OR  dbo.INVO_LST.TAG = 24) AND (dbo.HEAD_LST.DATE_N <= @FORMS___F_MENU_ANBAR_TARAZ___DT2) GROUP BY dbo.INVO_LST.ANBAR, dbo.INVO_LST.CODE, dbo.INVO_LST.TAG UNION  SELECT     dbo.INVO_LST.ANBAR, dbo.INVO_LST.CODE, SUM(dbo.INVO_LST.MEGHk) AS MEG, SUM(dbo.INVO_LST.AVRAGE*(dbo.INVO_LST.MEGHk - dbo.INVO_LST.MEGH_MAR))  AS SumOfMABL_K,  dbo.INVO_LST.TAG FROM         dbo.INVO_LST INNER JOIN  dbo.HEAD_LST ON dbo.INVO_LST.NUMBER = dbo.HEAD_LST.NUMBER AND dbo.INVO_LST.TAG = dbo.HEAD_LST.TAG WHERE     (dbo.INVO_LST.TAG = 22) AND (dbo.HEAD_LST.DATE_N <= @FORMS___F_MENU_ANBAR_TARAZ___DT2) GROUP BY dbo.INVO_LST.ANBAR, dbo.INVO_LST.CODE, dbo.INVO_LST.TAG UNION SELECT     dbo.INVO_LST.ANBARF, dbo.INVO_LST.CODE, SUM(dbo.INVO_LST.MEGHk - dbo.INVO_LST.MEGH_MAR) AS MEG, SUM(dbo.INVO_LST.MABL_K)  AS SumOfMABL_K, 6 AS TAG FROM         dbo.INVO_LST INNER JOIN  dbo.HEAD_LST ON dbo.INVO_LST.NUMBER = dbo.HEAD_LST.NUMBER AND dbo.INVO_LST.TAG = dbo.HEAD_LST.TAG WHERE     (dbo.INVO_LST.TAG = 5) AND (dbo.HEAD_LST.DATE_N <= @FORMS___F_MENU_ANBAR_TARAZ___DT2) GROUP BY dbo.INVO_LST.ANBARF, dbo.INVO_LST.CODE UNION  SELECT     dbo.ANBGRD_HEAD.GRD_ANBAR AS anbar, dbo.ANBGRD_LST.CODE, SUM((dbo.ANBGRD_LST.MOG - dbo.ANBGRD_LST.NUM3) * - 1) AS MEG,  SUM(dbo.ANBGRD_LST.MABL * ((dbo.ANBGRD_LST.MOG - dbo.ANBGRD_LST.NUM3) * - 1)) AS MABLk, 17 AS TAG FROM         dbo.ANBGRD_LST INNER JOIN  dbo.ANBGRD_HEAD ON dbo.ANBGRD_LST.GRD_NUM = dbo.ANBGRD_HEAD.GRD_NUM WHERE     ((dbo.ANBGRD_LST.MOG - dbo.ANBGRD_LST.NUM3) * - 1 > 0) AND (NOT (dbo.ANBGRD_HEAD.N_S IS NULL)) AND  (dbo.ANBGRD_HEAD.GRD_DATE <= @FORMS___F_MENU_ANBAR_TARAZ___DT2) GROUP BY dbo.ANBGRD_HEAD.GRD_ANBAR, dbo.ANBGRD_LST.CODE  UNION SELECT     ANBAR, CODE, SUM(MOGODI_A) AS MEG, SUM(MABL_A) AS SumOfMABL_A, 0 AS TAG FROM dbo.STUF_FSK GROUP BY ANBAR, CODE )
